   memoryCache.set(city.id,{record,expiresAt:Date.now()+CACHE_SECONDS*1000});
   const result={status:'success',record,cached:false};
   if(typeof caches!=='undefined'){const cacheResponse=json(result,200,{'Cache-Control':`public, max-age=${CACHE_SECONDS}`}),save=caches.default.put(cacheKey,cacheResponse).catch(()=>{});if(ctx?.waitUntil)ctx.waitUntil(save);else await save;}
